import { useCallback, useEffect, useMemo, useState, type FormEvent, type ReactNode } from 'react';
import { AlertTriangle, ArrowRight, Bell, Boxes, CalendarClock, Check, ChevronRight, ClipboardCheck, Download, Eye, FileCheck, FileText, HeartPulse, History, IndianRupee, LayoutDashboard, LogOut, Mail, Menu, MessageSquare, Package, PackagePlus, Plus, Receipt, RefreshCw, Search, Send, Settings2, ShieldCheck, ShoppingCart, Sparkles, Store, ThumbsDown, Trash2, UserRound, X } from 'lucide-react';
import { Landing, AuthPage, CustomerAuthPage } from './Public';
import { Brand } from './Brand';
import { request, type Customer, type Invoice, type Product, type Quote, type Workspace } from './api';
import { PlatformAdmin, SuperAdminLogin } from './PlatformAdmin';

type View = 'dashboard'|'quotations'|'quote'|'approvals'|'approval'|'fulfillment'|'fulfillment-detail'|'subscriptions'|'billing'|'portal'|'invoices'|'invoice'|'health'|'reports'|'products'|'product'|'customers'|'customer'|'policies'|'access';
const money = (value:number|string) => new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR',maximumFractionDigits:0}).format(Number(value));
const date = (value:string) => new Intl.DateTimeFormat('en-US',{month:'short',day:'numeric',year:'numeric'}).format(new Date(value));
const label = (value:string) => value.replaceAll('_',' ').toLowerCase().replace(/\b\w/g,(c)=>c.toUpperCase());

const nav:[View,string,ReactNode][] = [
  ['dashboard','Overview',<LayoutDashboard/>],['quotations','Quotations',<FileText/>],['approvals','Approvals',<ClipboardCheck/>],['fulfillment','Fulfillment',<Boxes/>],['subscriptions','Subscriptions',<RefreshCw/>],['invoices','Invoices',<IndianRupee/>],['health','Deal health',<HeartPulse/>],['reports','Reports',<IndianRupee/>],['products','Products',<Package/>],['customers','Customers',<Store/>],['policies','Rules',<ShieldCheck/>],
  ['access','User access',<UserRound/>],
];

export function App(){
  const [route,setRoute]=useState(()=>window.location.pathname);
  const [checking,setChecking]=useState(true);
  const navigate=(path:string)=>{window.history.pushState({},'',path);setRoute(window.location.pathname);window.scrollTo(0,0)};
  useEffect(()=>{const sync=()=>setRoute(window.location.pathname);window.addEventListener('popstate',sync);return()=>window.removeEventListener('popstate',sync)},[]);
  useEffect(()=>{document.title=route==='/'?'DealOS — Less friction. More forward.':route.startsWith('/customer')?'Customer Portal — DealOS':route==='/login/super-admin'?'Platform Owner — DealOS':route.includes('sign-up')||route==='/signup'?'Create your account — DealOS':route.includes('sign-in')||route==='/signin'?'Sign in — DealOS':'Workspace — DealOS'},[route]);
  const [workspace,setWorkspace]=useState<Workspace|null>(null); const [view,setView]=useState<View>('dashboard');
  const [selectedId,setSelectedId]=useState(''); const [busy,setBusy]=useState(false); const [error,setError]=useState(''); const [toast,setToast]=useState('');
  const load=useCallback(async()=>{try{setError('');const data=await request<Workspace>('/workspace');setWorkspace(data);if(data.user.role!=='ADMIN'&&!data.user.moduleAccess.includes('dashboard'))setView((data.user.moduleAccess[0] as View)??'dashboard');}catch(e){setWorkspace(null);setError(e instanceof Error?e.message:'Unable to load DealOS');}},[]);
  useEffect(()=>{request('/auth/me').then(load).catch(()=>undefined).finally(()=>setChecking(false))},[load]);
  useEffect(()=>{ const context=(document as Document & {modelContext?:{registerTool:(tool:unknown,options?:{signal?:AbortSignal})=>void}}).modelContext; if(!context?.registerTool)return; const controller=new AbortController(); context.registerTool({name:'read_dealos_workspace',title:'Read DealOS workspace',description:'Return the current DealOS screen and visible aggregate counts without changing data.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({screen:view,counts:workspace?{quotes:workspace.quotes.length,pendingApprovals:workspace.quotes.flatMap(q=>q.approvals).filter(a=>a.state==='PENDING').length,alerts:workspace.alerts.filter(a=>!a.resolved).length}:null})},{signal:controller.signal}); return()=>controller.abort();},[view,workspace]);
  const mutate=async(path:string,body:unknown,method='POST',message='Updated')=>{if(workspace?.user.viewContext?.readOnly){setError('View As mode is read-only. Exit the simulated context before making changes.');return}try{setBusy(true);setError('');await request(path,{method,body:JSON.stringify(body)});await load();setToast(message);setTimeout(()=>setToast(''),2400);}catch(e){setError(e instanceof Error?e.message:'Action failed')}finally{setBusy(false)}};
  if(route==='/')return <Landing/>;
  if(['/sign-up','/signup'].includes(route))return <AuthPage signup onSuccess={async()=>{await load();navigate('/app')}}/>;
  if(['/sign-in','/signin','/login'].includes(route))return <AuthPage onSuccess={async()=>{await load();navigate('/app')}} error={error}/>;
  if(route==='/login/super-admin')return <SuperAdminLogin onSuccess={async()=>{await load();navigate('/app')}}/>;
  if(['/customer','/customer/sign-in'].includes(route)){
    if(checking)return <div className="customer-route-loading" role="status">Opening your secure deal room…</div>;
    if(!workspace||workspace.user.role!=='CUSTOMER')return <CustomerAuthPage signedInRole={workspace?.user.role} onSuccess={async()=>{await load();navigate('/customer')}}/>;
    return <div className="app-shell customer-route-shell"><main className="portal-main"><section className="content"><CustomerPortalV2 data={workspace} mutate={mutate} reload={load} logout={async()=>{await request('/auth/logout',{method:'POST',body:'{}'});setWorkspace(null);navigate('/customer/sign-in')}}/></section></main>{busy&&<div className="busy"><RefreshCw/> Saving changes…</div>}{toast&&<div className="toast"><Check/>{toast}</div>}</div>;
  }
  if(route!=='/app')return <div className="not-found"><h1>This page took a wrong turn.</h1><a className="cta" href="/">Back to DealOS <ArrowRight/></a></div>;
  if(checking)return <div className="not-found" role="status">Opening your workspace…</div>;
  if(!workspace)return <AuthPage onSuccess={load} error={error}/>;
  const open=(next:View,id='')=>{setSelectedId(id);setView(next);setError('');};
  const logout=async()=>{const destination=workspace.user.actorType==='PLATFORM_OWNER'?'/login/super-admin':'/sign-in';await request('/auth/logout',{method:'POST',body:'{}'});setWorkspace(null);navigate(destination)};
  if(workspace.user.platformSuperAdmin&&!workspace.user.viewContext)return <PlatformAdmin logout={logout} onContextChanged={load}/>;
  const exitView=async()=>{await request('/platform/view-as/exit',{method:'POST',body:'{}'});await load()};
  const customers=workspace.customers??[]; const quote=workspace.quotes.find(q=>q.id===selectedId)??workspace.quotes[0]; const invoice=workspace.invoices.find(i=>i.id===selectedId)??workspace.invoices[0]; const product=workspace.products.find(p=>p.id===selectedId)??workspace.products[0]; const customer=customers.find(c=>c.id===selectedId)??customers[0];
  const content:Record<View,ReactNode>={
    dashboard:<Dashboard data={workspace} open={open}/>, quotations:<Quotations data={workspace} open={open} mutate={mutate}/>, quote:<QuoteDetail quote={quote} products={workspace.products} mutate={mutate}/>, approvals:<Approvals data={workspace} open={open}/>, approval:<ApprovalDetail quote={quote} mutate={mutate} role={workspace.user.role}/>, fulfillment:<Fulfillment data={workspace} open={open}/>, 'fulfillment-detail':<FulfillmentDetail quote={quote} mutate={mutate}/>, subscriptions:<Subscriptions data={workspace} open={open}/>, billing:<Billing subscription={workspace.subscriptions.find(s=>s.id===selectedId)??workspace.subscriptions[0]} mutate={mutate}/>, portal:<Portal quote={quote} mutate={mutate}/>, invoices:<Invoices data={workspace} open={open} mutate={mutate}/>, invoice:<InvoiceDetail invoice={invoice} mutate={mutate}/>, health:<Health data={workspace} mutate={mutate}/>, reports:<Reports data={workspace}/>, products:<Products data={workspace} open={open} mutate={mutate}/>, product:<ProductDetail product={product} mutate={mutate}/>, customers:<Customers data={workspace} open={open} mutate={mutate}/>, customer:<CustomerDetailV2 customer={customer} open={open} mutate={mutate}/>, policies:<Policies data={workspace} mutate={mutate}/>, access:<AccessControl data={workspace} reload={load}/>,
  };
  const portalMode=workspace.user.role==='CUSTOMER';
  const visibleNav=nav.filter(([id])=>id==='access'?workspace.user.role==='ADMIN':workspace.user.role==='ADMIN'||workspace.user.moduleAccess.includes(id));
  return <div className="app-shell">
    {workspace.user.viewContext&&<div className="view-as-banner"><Eye/><span><b>Read-only View As:</b> {workspace.user.viewContext.organizationName}{workspace.user.viewContext.simulatedUserId?' · simulated user context':''} · Real actor: {workspace.user.viewContext.realActor.name}</span><button onClick={exitView}>Exit View As <X/></button></div>}
    {!portalMode&&<aside><Brand /><nav>{visibleNav.map(([id,text,icon])=><button key={id} aria-label={text} className={view===id||related(view,id)?'active':''} onClick={()=>open(id)}>{icon}<span>{text}</span>{id==='approvals'&&<em>{workspace.quotes.flatMap(q=>q.approvals).filter(a=>a.state==='PENDING').length}</em>}</button>)}</nav><div className="sidebar-foot"><div className="avatar">{workspace.user.name.split(' ').map(p=>p[0]).join('')}</div><div><b>{workspace.user.name}</b><small>{workspace.user.role==='ADMIN'?'Organization admin':'Team member'}</small></div><button aria-label="Log out" onClick={logout}><LogOut/></button></div></aside>}
    <main className={portalMode?'portal-main':''}>{!portalMode&&<header className="workspace-header"><div><h1>{title(view)}</h1></div></header>}{error&&<div className="error"><AlertTriangle/>{error}<button onClick={()=>setError('')}><X/></button></div>}<section className="content">{portalMode?<CustomerPortalV2 data={workspace} mutate={mutate} reload={load} logout={logout}/>:content[view]}</section></main>
    {busy&&<div className="busy"><RefreshCw/> Saving changes…</div>}{toast&&<div className="toast"><Check/>{toast}</div>}
  </div>;
}

function Dashboard({data,open}:{data:Workspace;open:(v:View,id?:string)=>void}){const pending=data.quotes.flatMap(q=>q.approvals).filter(a=>a.state==='PENDING').length;return <><div className="metric-grid"><Metric label="Pipeline value" value={money(data.quotes.reduce((s,q)=>s+Number(q.total),0))} note={`${data.quotes.length} active quotations`} tone="dark"/><Metric label="Pending approvals" value={String(pending)} note="Requires reviewer action"/><Metric label="At-risk deals" value={String(data.alerts.filter(a=>!a.resolved).length)} note="Across discounts and delivery" tone="warn"/><Metric label="Open invoices" value={money(data.invoices.filter(i=>i.state!=='PAID').reduce((s,i)=>s+Number(i.amount)-Number(i.paidAmount),0))} note="Outstanding balance"/></div><div className="two-col"><Panel title="Recent deal activity" action={<button onClick={()=>open('quotations')}>View pipeline <ChevronRight/></button>}><DealTable quotes={data.quotes} open={open}/></Panel><Panel title="Attention queue"><div className="attention">{data.alerts.slice(0,3).map(a=><button key={a.id} onClick={()=>open('health')}><span className={`alert-dot ${a.severity.toLowerCase()}`}/><span><b>{a.title}</b><small>{a.detail}</small></span><ChevronRight/></button>)}</div></Panel></div></>}
function Quotations({data,open,mutate}:{data:Workspace;open:(v:View,id?:string)=>void;mutate:Function}){const[newOpen,setNewOpen]=useState(false);const create=async(e:FormEvent<HTMLFormElement>)=>{e.preventDefault();const f=new FormData(e.currentTarget);await mutate('/quotations',{customer:f.get('customer'),customerTier:f.get('tier')},'POST','Quotation created');setNewOpen(false)};return <><div className="toolbar"><div className="search"><Search/><input placeholder="Search quotations"/></div><button className="button primary" onClick={()=>setNewOpen(true)}><Plus/>New quotation</button></div><div className="kanban">{['DRAFT','PENDING_APPROVAL','APPROVED','NEGOTIATION','CONFIRMED'].map(stage=><div className="lane" key={stage}><div className="lane-title"><span>{label(stage)}</span><em>{data.quotes.filter(q=>q.stage===stage).length}</em></div>{data.quotes.filter(q=>q.stage===stage).map(q=><button className="deal-card" key={q.id} onClick={()=>open('quote',q.id)}><small>{q.number}</small><h3>{q.customer}</h3><b>{money(q.total)}</b><div><span>{q.customerTier}</span><span>{date(q.updatedAt)}</span></div></button>)}</div>)}</div>{newOpen&&<Modal title="New quotation" close={()=>setNewOpen(false)}><form onSubmit={create} className="form"><label>Customer<input name="customer" defaultValue="Vertex Systems" required/></label><label>Customer tier<select name="tier"><option>Gold</option><option>Silver</option><option>Bronze</option></select></label><button className="button primary">Create draft</button></form></Modal>}</>}
type CommerceLine={productId:string;quantity:number;discount:number};
const lineAmount=(product:Product|undefined,line:CommerceLine)=>{const price=Number(product?.price??0);const net=price*line.quantity*(1-line.discount/100);const tax=net*Number(product?.taxRate??0)/100;return {net,tax,total:net+tax}};
function ProductLineEditor({products,lines,setLines,readonly=false}:{products:Product[];lines:CommerceLine[];setLines:(fn:(value:CommerceLine[])=>CommerceLine[])=>void;readonly?:boolean}){const active=products.filter(p=>p.active);const fallback=active[0]?.id??'';const addLine=()=>fallback&&setLines(v=>[...v,{productId:fallback,quantity:1,discount:0}]);const update=(index:number,patch:Partial<CommerceLine>)=>setLines(v=>v.map((line,i)=>i===index?{...line,...patch}:line));const remove=(index:number)=>setLines(v=>v.filter((_,i)=>i!==index));const subtotal=lines.reduce((sum,line)=>sum+lineAmount(products.find(p=>p.id===line.productId),line).total,0);return <div className="catalog-line-editor">{lines.map((line,index)=>{const product=products.find(p=>p.id===line.productId);const amount=lineAmount(product,line);return <div className="catalog-line" key={`${line.productId}-${index}`}><label>Catalog product<select value={line.productId} disabled={readonly} onChange={e=>update(index,{productId:e.target.value})}>{active.map(p=><option key={p.id} value={p.id}>{p.name} · {p.sku} · {money(p.price)}</option>)}</select></label><div className="line-fields"><label>Qty<input type="number" min="1" value={line.quantity} disabled={readonly} onChange={e=>update(index,{quantity:Number(e.target.value)})}/></label><label>Discount %<input type="number" min="0" max="100" value={line.discount} disabled={readonly} onChange={e=>update(index,{discount:Number(e.target.value)})}/></label><label>GST<input value={`${product?.taxRate??0}%`} disabled/></label></div><div className="line-preview"><span><b>{product?.category??'Product'}</b><small>{product?.unit??'Unit'} · {product?.cadence??'One-time'}</small></span><strong>{money(amount.total)}</strong>{!readonly&&<button className="icon-button" type="button" aria-label="Remove line" onClick={()=>remove(index)} disabled={lines.length===1}><Trash2/></button>}</div></div>})}<div className="catalog-line-footer"><button type="button" className="button ghost" disabled={readonly||!fallback} onClick={addLine}><Plus/>Add synced catalog line</button><strong>{money(subtotal)}</strong></div>{!active.length&&<Empty text="Add an active product before creating invoice or quotation lines."/>}</div>}
function QuoteDetail({quote,products,mutate}:{quote?:Quote;products:Product[];mutate:Function}){const[lines,setLines]=useState<CommerceLine[]>(()=>quote?.lines.map(l=>({productId:l.productId,quantity:l.quantity,discount:Number(l.discount)}))??[]);useEffect(()=>setLines(quote?.lines.map(l=>({productId:l.productId,quantity:l.quantity,discount:Number(l.discount)}))??[]),[quote?.id]);useEffect(()=>{const first=products.find(p=>p.active);if(quote?.stage==='DRAFT'&&!lines.length&&first)setLines([{productId:first.id,quantity:1,discount:0}])},[quote?.stage,products.length,lines.length]);if(!quote)return <Empty text="Create a quotation to begin."/>;const add=(product:Product)=>setLines(v=>v.some(l=>l.productId===product.id)?v:[...v,{productId:product.id,quantity:1,discount:0}]);const save=()=>mutate(`/quotations/${quote.id}/draft`,{version:quote.version,orderDiscount:Number(quote.orderDiscount),lines},'PUT','Draft saved');return <><div className="detail-head"><div><span className="status">{label(quote.stage)}</span><h2>{quote.number} · {quote.customer}</h2><p>{quote.customerTier} customer · Version {quote.version}</p></div><div className="actions"><button className="button ghost" onClick={save} disabled={quote.stage!=='DRAFT'||!lines.length}>Save draft</button><button className="button primary" onClick={()=>mutate(`/quotations/${quote.id}/submit`,{},'POST','Submitted for approval')} disabled={quote.stage!=='DRAFT'}>Submit for approval</button>{quote.stage==='APPROVED'&&<button className="button primary" onClick={()=>mutate(`/quotations/${quote.id}/send`,{},'POST','Sent to customer portal')}>Send to customer</button>}</div></div><div className="quote-layout"><Panel title="Commercial lines">{quote.stage==='DRAFT'?<ProductLineEditor products={products} lines={lines} setLines={setLines}/>:<div className="table-wrap"><table><thead><tr><th>Product</th><th>Qty</th><th>List price</th><th>Discount</th><th>Limit</th><th>Net</th></tr></thead><tbody>{lines.map((line,index)=>{const p=products.find(x=>x.id===line.productId);const persisted=quote.lines.find(x=>x.productId===line.productId);return <tr key={`${line.productId}-${index}`}><td><b>{p?.name}</b><small>{p?.category}{p?.cadence?` · ${p.cadence}`:''}</small></td><td>{line.quantity}</td><td>{money(p?.price??0)}</td><td>{line.discount}%</td><td>{persisted?`${persisted.allowedDiscount}%`:'-'}</td><td>{money(lineAmount(p,line).net)}</td></tr>})}</tbody></table></div>}<div className="totals"><span>Deal total <b>{money(quote.total)}</b></span><span>Margin <b>{money(quote.margin)}</b></span><span className={Number(quote.riskScore)>0?'risk':''}>Risk excess <b>{quote.riskScore} pts</b></span></div></Panel><Panel title="Synced catalog suggestions"><p className="muted">Products created in the Product module appear here after the workspace refresh.</p><div className="suggestions">{products.filter(p=>p.active&&!lines.some(l=>l.productId===p.id)).slice(0,3).map(p=><div key={p.id}><span className="product-icon"><Sparkles/></span><span><b>{p.name}</b><small>{p.sku} · +{money(Number(p.price)-Number(p.cost))} margin · {p.category}</small></span><button onClick={()=>add(p)} disabled={quote.stage!=='DRAFT'}>Add</button></div>)}</div></Panel></div></>}
function Approvals({data,open}:{data:Workspace;open:(v:View,id?:string)=>void}){const qs=data.quotes.filter(q=>q.approvals.length);return <Panel title="Approval queue"><div className="filter-row"><button className="chip active">Pending</button><button className="chip">Returned</button><button className="chip">Approved</button></div><div className="table-wrap"><table><thead><tr><th>Quotation</th><th>Customer</th><th>Risk</th><th>Current step</th><th>Status</th><th/></tr></thead><tbody>{qs.map(q=><tr key={q.id}><td><b>{q.number}</b></td><td>{q.customer}</td><td><span className="risk-pill">{q.riskScore} pts</span></td><td>{q.approvals.find(a=>a.state==='PENDING')?.step??'Complete'}</td><td><Status value={q.stage}/></td><td><button onClick={()=>open('approval',q.id)}>Review <ChevronRight/></button></td></tr>)}</tbody></table></div></Panel>}
function ApprovalDetail({quote,mutate,role}:{quote?:Quote;mutate:Function;role:string}){const[reason,setReason]=useState('Commercial terms reviewed against policy.');if(!quote)return <Empty text="No approval selected."/>;const current=quote.approvals.find(a=>a.state==='PENDING');return <><div className="detail-head"><div><span className="status warning">Approval review</span><h2>{quote.number} · {quote.customer}</h2><p>Opened by {quote.customerTier} account · {money(quote.total)}</p></div><div className="risk-score"><b>{quote.riskScore}</b><span>risk excess<br/>points</span></div></div><Panel title="Why this quotation was flagged"><div className="table-wrap"><table><thead><tr><th>Line</th><th>Discount given</th><th>Limit allowed</th><th>Outcome</th></tr></thead><tbody>{quote.lines.map(l=><tr key={l.id}><td>{l.product.name}</td><td>{l.discount}%</td><td>{l.allowedDiscount}%</td><td>{Number(l.discount)>Number(l.allowedDiscount)?<span className="risk-pill">{Number(l.discount)-Number(l.allowedDiscount)} pts over</span>:<span className="good">Within policy</span>}</td></tr>)}</tbody></table></div><div className="explain"><AlertTriangle/>The highest line excess and the value-weighted pattern determine the required review path.</div></Panel><div className="approval-track">{quote.approvals.map((a,i)=><div className={a.state.toLowerCase()} key={a.id}><i>{a.state==='APPROVED'?<Check/>:i+1}</i><span><b>{a.step}</b><small>{label(a.state)}</small></span></div>)}</div><Panel title="Decision"><div className="decision"><label>Review reason<textarea value={reason} onChange={e=>setReason(e.target.value)}/></label><div className="actions"><button className="button primary" disabled={!current||!(role==='ADMIN'||(current.step==='Sales Manager'&&role==='MANAGER')||(current.step==='Finance'&&role==='FINANCE'))} onClick={()=>mutate(`/approvals/${current?.id}/decision`,{decision:'APPROVE',reason},'POST','Approval recorded')}>Approve</button><button className="button warn" disabled={!current} onClick={()=>mutate(`/approvals/${current?.id}/decision`,{decision:'RETURN',reason},'POST','Returned for revision')}>Return for revision</button><button className="button danger" disabled={!current} onClick={()=>mutate(`/approvals/${current?.id}/decision`,{decision:'REJECT',reason},'POST','Quotation rejected')}>Reject</button></div></div></Panel></>}
function Fulfillment({data,open}:{data:Workspace;open:(v:View,id?:string)=>void}){return <><div className="metric-grid three">{data.warehouses.map(w=><Metric key={w.id} label={w.name} value={String(w.stocks.reduce((s,x)=>s+x.onHand-x.reserved,0))} note={`${money(w.shippingCost)} base shipping · Priority ${w.priority}`}/>)}</div><Panel title="Orders awaiting fulfillment"><DealTable quotes={data.quotes.filter(q=>q.stage==='CONFIRMED')} open={(v,id)=>open('fulfillment-detail',id)} fulfillment/></Panel></>}
function FulfillmentDetail({quote,mutate}:{quote?:Quote;mutate:Function}){if(!quote)return <Empty text="No confirmed order selected."/>;const f=quote.fulfillment;return <><div className="detail-head"><div><span className="status">{f?label(f.state):'Split pending'}</span><h2>Fulfillment · {quote.number}</h2><p>{quote.customer} · physical products only</p></div><button className="button primary" onClick={()=>mutate(`/fulfillment/${quote.id}/allocate`,{},'POST','Stock allocation committed')} disabled={!!f}>Accept suggested split</button></div><div className="two-col"><Panel title="Recommended warehouse split">{f?<div className="split-list">{f.split.split.map((row,i)=><div key={i}><Store/><span><b>{row.warehouseName}</b><small>{quote.lines.find(l=>l.productId===row.productId)?.product.name}</small></span><strong>{row.quantity} units</strong></div>)}{f.split.backorders.map((row,i)=><div className="backorder" key={`b${i}`}><AlertTriangle/><span><b>Backorder</b><small>{quote.lines.find(l=>l.productId===row.productId)?.product.name}</small></span><strong>{row.quantity} units</strong></div>)}</div>:<Empty text="Commit the calculated split to reserve available stock."/>}</Panel><Panel title="Fulfillment impact"><Metric label="Estimated cost" value={money(f?.estimatedCost??0)} note={`${f?.shipmentCount??0} shipments`}/><p className="explain plain">Manual overrides must still respect live availability and require a reason. Shipped quantities are never moved during consolidation.</p></Panel></div></>}
function Subscriptions({data,open}:{data:Workspace;open:(v:View,id?:string)=>void}){return <Panel title="Recurring subscriptions"><div className="table-wrap"><table><thead><tr><th>Customer</th><th>Plan</th><th>Cadence</th><th>Amount</th><th>Next bill</th><th>Status</th><th/></tr></thead><tbody>{data.subscriptions.map(s=><tr key={s.id}><td>{s.customer}</td><td><b>{s.productName}</b></td><td>{s.cadence}</td><td>{money(s.amount)}</td><td>{date(s.nextBillAt)}</td><td><Status value={s.state}/></td><td><button onClick={()=>open('billing',s.id)}>Manage <ChevronRight/></button></td></tr>)}</tbody></table></div></Panel>}
function Billing({subscription,mutate}:{subscription?:Workspace['subscriptions'][number];mutate:Function}){const[amount,setAmount]=useState(Number(subscription?.amount??0));if(!subscription)return <Empty text="No recurring subscription selected."/>;const schedule=subscription.schedule??[subscription.nextBillAt];return <><div className="detail-head"><div><span className="status">{label(subscription.state)}</span><h2>{subscription.customer} · {subscription.productName}</h2><p>{subscription.cadence} recurring plan</p></div></div><div className="two-col"><Panel title="Recurring schedule"><div className="schedule">{schedule.map((billAt,i)=><div key={billAt}><span>{i===0?'Next billing':'Upcoming'}</span><b>{date(billAt)}</b><strong>{money(subscription.amount)}</strong></div>)}</div></Panel><Panel title="Modify subscription"><div className="form"><label>Recurring amount<input type="number" min="1" value={amount} onChange={e=>setAmount(Number(e.target.value))}/></label><div className="actions"><button className="button primary" onClick={()=>mutate(`/subscriptions/${subscription.id}/change`,{amount},'POST','Subscription updated')}>Apply change</button><button className="button danger" onClick={()=>mutate(`/subscriptions/${subscription.id}/change`,{cancel:true},'POST','Subscription cancelled')} disabled={subscription.state==='CANCELLED'}>Cancel subscription</button></div><p className="muted">Changes are audited. A production billing policy should preview proration or credit before commit.</p></div></Panel></div></>}
function Portal({quote,mutate}:{quote?:Quote;mutate:Function}){const[message,setMessage]=useState('');const[counter,setCounter]=useState(0);if(!quote)return <Empty text="No quotation is available in your portal."/>;return <div className="portal-card"><div className="portal-title"><div className="brand"><span>D</span><strong>DealOS</strong></div><span className="status warning">{label(quote.stage)}</span></div><div className="portal-hero"><span className="eyebrow">Quotation {quote.number}</span><h2>{quote.customer}</h2><p>Review the commercial terms, ask a line-level question, or request a change.</p><strong>{money(quote.total)}</strong></div><div className="table-wrap"><table><thead><tr><th>Product</th><th>Quantity</th><th>Unit price</th><th>Discount</th><th>Net</th></tr></thead><tbody>{quote.lines.map(l=><tr key={l.id}><td><b>{l.product.name}</b><small>{l.product.description}</small></td><td>{l.quantity}</td><td>{money(l.unitPrice)}</td><td>{l.discount}%</td><td>{money(Number(l.unitPrice)*l.quantity*(1-Number(l.discount)/100))}</td></tr>)}</tbody></table></div><div className="portal-actions"><label>Comment or change request<textarea placeholder="Ask about a line or explain your request" value={message} onChange={e=>setMessage(e.target.value)}/></label><label>Counter discount (%)<input type="number" min="0" max="100" value={counter} onChange={e=>setCounter(Number(e.target.value))}/></label><div className="actions"><button className="button ghost" disabled={!message.trim()} onClick={()=>mutate(`/portal/quotations/${quote.id}/message`,counter>0?{message,counterDiscount:counter}:{message},'POST',counter>0?'Proposal sent':'Comment posted')}>Submit request</button><button className="button primary" disabled={quote.stage!=='APPROVED'} onClick={()=>mutate(`/portal/quotations/${quote.id}/confirm`,{},'POST','Quotation confirmed')}>Confirm quotation</button></div></div>{quote.stage!=='APPROVED'&&<div className="explain"><ShieldCheck/>Confirmation unlocks after the current terms complete approval.</div>}{quote.negotiation.length>0&&<Panel title="Discussion">{quote.negotiation.map(n=><div className="comment" key={n.id}><b>{n.author}</b><span>{n.message}</span><small>{date(n.createdAt)}{n.counterDiscount?` · ${n.counterDiscount}% proposed`:''}</small></div>)}</Panel>}</div>}
function Invoices({data,open,mutate}:{data:Workspace;open:(v:View,id?:string)=>void;mutate:Function}){const[creating,setCreating]=useState(false);return <><div className="toolbar"><div className="filter-row"><button className="chip active">All invoices</button><button className="chip">Unpaid</button><button className="chip">Paid</button></div><button className="button primary" onClick={()=>setCreating(true)}><Plus/>Create invoice</button></div><Panel title="Invoices"><div className="table-wrap"><table><thead><tr><th>Invoice</th><th>Customer</th><th>Amount</th><th>Balance</th><th>Due date</th><th>Status</th><th/></tr></thead><tbody>{data.invoices.map(i=><tr key={i.id}><td><b>{i.number}</b></td><td>{i.customer}</td><td>{money(i.amount)}</td><td>{money(Number(i.amount)-Number(i.paidAmount))}</td><td>{date(i.dueAt)}</td><td><Status value={i.state}/></td><td><button onClick={()=>open('invoice',i.id)}>Open <ChevronRight/></button></td></tr>)}</tbody></table></div></Panel>{creating&&<CreateInvoiceModal data={data} mutate={mutate} close={()=>setCreating(false)}/>}</>}
function InvoiceDetail({invoice,mutate}:{invoice?:Invoice;mutate:Function}){const[amount,setAmount]=useState(invoice?Number(invoice.amount)-Number(invoice.paidAmount):0);const[ref,setRef]=useState('BANK-2026-');if(!invoice)return <Empty text="No invoice selected."/>;return <><div className="detail-head"><div><span className="status">{label(invoice.state)}</span><h2>{invoice.number} · {invoice.customer}</h2><p>Due {date(invoice.dueAt)}</p></div><div className="risk-score neutral"><b>{money(Number(invoice.amount)-Number(invoice.paidAmount))}</b><span>outstanding</span></div></div><div className="two-col"><Panel title="Invoice lines"><div className="table-wrap"><table><thead><tr><th>Description</th><th>Amount</th></tr></thead><tbody>{invoice.lines.map((l,i)=><tr key={i}><td>{l.description}</td><td>{money(l.amount)}</td></tr>)}</tbody><tfoot><tr><th>Total</th><th>{money(invoice.amount)}</th></tr></tfoot></table></div></Panel><Panel title="Record payment"><div className="form"><label>Amount<input type="number" min="1" max={Number(invoice.amount)-Number(invoice.paidAmount)} value={amount} onChange={e=>setAmount(Number(e.target.value))}/></label><label>Bank reference<input value={ref} onChange={e=>setRef(e.target.value)}/></label><button className="button primary" disabled={invoice.state==='PAID'} onClick={()=>mutate(`/invoices/${invoice.id}/payments`,{amount,reference:ref},'POST','Payment recorded')}>Record payment</button><p className="muted">This records verified settlement evidence. It does not initiate a bank transfer.</p></div></Panel></div></>}
function Health({data,mutate}:{data:Workspace;mutate:Function}){return <><div className="metric-grid three"><Metric label="Stalled deals" value={String(data.alerts.filter(a=>a.kind==='STALLED').length)} note="No activity past threshold"/><Metric label="Discount anomalies" value={String(data.alerts.filter(a=>a.kind==='DISCOUNT_ANOMALY').length)} note="Outside representative baseline" tone="warn"/><Metric label="Delivery slippage" value={String(data.alerts.filter(a=>a.kind==='DELIVERY_SLIPPAGE').length)} note="Promise date is at risk"/></div><Panel title="Actionable alerts"><div className="alert-list">{data.alerts.map(a=><div key={a.id}><span className={`alert-icon ${a.severity.toLowerCase()}`}><AlertTriangle/></span><span><b>{a.title}</b><small>{a.detail}</small></span><Status value={a.severity}/><button className="button ghost" disabled={a.nudged} onClick={()=>mutate(`/alerts/${a.id}/nudge`,{},'POST','Internal nudge created')}>{a.nudged?'Nudged':'Nudge owner'}</button></div>)}</div></Panel></>}
function Reports({data}:{data:Workspace}){const created=data.quotes.length;const approved=data.quotes.filter(q=>['APPROVED','CONFIRMED'].includes(q.stage)).length;const value=data.quotes.reduce((s,q)=>s+Number(q.total),0);const bars=data.quotes.map(q=>({name:q.customer,value:Number(q.total),pct:value?Number(q.total)/Math.max(...data.quotes.map(x=>Number(x.total)))*100:0}));return <><div className="toolbar report-filters"><label>Period<select><option>This month</option><option>This quarter</option></select></label><label>Sales team<select><option>All assigned teams</option></select></label><label>Approval status<select><option>All statuses</option></select></label><button className="button ghost">Export PDF</button><button className="button ghost">Export XLS</button></div><div className="metric-grid three"><Metric label="Quotations created" value={String(created)} note="Current authorized dataset"/><Metric label="Approved / confirmed" value={String(approved)} note={`${created?Math.round(approved/created*100):0}% conversion`}/><Metric label="Pipeline value" value={money(value)} note="INR one-time equivalent in demo data" tone="dark"/></div><Panel title="Value by customer"><div className="bar-chart">{bars.map(b=><div key={b.name}><span>{b.name}</span><i><em style={{width:`${b.pct}%`}}/></i><b>{money(b.value)}</b></div>)}</div></Panel></>}
function Products({data,open,mutate}:{data:Workspace;open:(v:View,id?:string)=>void;mutate:Function}){const[creating,setCreating]=useState(false);const[query,setQuery]=useState('');const active=data.products.filter(p=>p.active);const categories=new Set(data.products.map(p=>p.category));const stock=data.products.reduce((sum,p)=>sum+p.stocks.reduce((inner,row)=>inner+row.onHand-row.reserved,0),0);const filtered=data.products.filter(p=>[p.name,p.sku,p.category,p.description].join(' ').toLowerCase().includes(query.toLowerCase()));return <div className="product-module"><div className="product-command"><div><span className="eyebrow">Catalog control</span><p>Create products once, then reuse them in quotations, invoices, stock, and customer documents.</p></div><button className="button primary" onClick={()=>setCreating(true)}><Plus/>Create Product</button></div><div className="product-stat-grid"><Metric label="Active products" value={String(active.length)} note="Ready for quotations and invoices"/><Metric label="Categories" value={String(categories.size)} note="Grouped catalog families"/><Metric label="Available stock" value={String(stock)} note="Across linked warehouses"/></div><section className="product-catalog-card"><div className="product-catalog-head"><div><h3>Catalog Items</h3><p>{filtered.length} visible item{filtered.length===1?'':'s'}</p></div><div className="search"><Search/><input placeholder="Search by product, SKU, or category" value={query} onChange={e=>setQuery(e.target.value)}/></div></div><div className="table-wrap"><table><thead><tr><th>Product</th><th>Category</th><th>SKU</th><th>Price</th><th>Cost</th><th>Tax</th><th>Status</th><th/></tr></thead><tbody>{filtered.map(p=><tr key={p.id}><td><b>{p.name}</b><small>{p.description}</small></td><td>{p.category}</td><td>{p.sku}</td><td>{money(p.price)}</td><td>{money(p.cost)}</td><td>{p.taxRate}%</td><td><Status value={p.active?'Active':'Inactive'}/></td><td><button onClick={()=>open('product',p.id)}>Edit <ChevronRight/></button></td></tr>)}</tbody></table>{!filtered.length&&<Empty text="No products match your search."/>}</div></section>{creating&&<CreateProductModal mutate={mutate} close={()=>setCreating(false)}/>}</div>}
function ProductDetail({product,mutate}:{product?:Product;mutate:Function}){const[price,setPrice]=useState(Number(product?.price??0));const[cost,setCost]=useState(Number(product?.cost??0));useEffect(()=>{setPrice(Number(product?.price??0));setCost(Number(product?.cost??0))},[product?.id]);if(!product)return <Empty text="No product selected."/>;return <><div className="detail-head"><div><span className="status">{product.active?'Active':'Archived'}</span><h2>{product.name}</h2><p>{product.sku} · {product.category}</p></div><button className="button primary" onClick={()=>mutate(`/products/${product.id}`,{price,cost,active:product.active},'PATCH','Product updated')}>Save product</button></div><div className="two-col"><Panel title="General information"><div className="form grid"><label>Product name<input value={product.name} disabled/></label><label>Category<input value={product.category} disabled/></label><label>Unit<input value={product.unit} disabled/></label><label>Tax rate<input value={`${product.taxRate}%`} disabled/></label><label>Price<input type="number" value={price} onChange={e=>setPrice(Number(e.target.value))}/></label><label>Cost<input type="number" value={cost} onChange={e=>setCost(Number(e.target.value))}/></label></div></Panel><Panel title="Inventory & billing"><div className="facts"><div><span>Recurring</span><b>{product.recurring?'Yes':'No'}</b></div><div><span>Cadence</span><b>{product.cadence??'One-time'}</b></div>{product.stocks.map(s=><div key={s.warehouse.name}><span>{s.warehouse.name}</span><b>{s.onHand-s.reserved} available</b></div>)}</div></Panel></div></>}
function Customers({data,open,mutate}:{data:Workspace;open:(v:View,id?:string)=>void;mutate:Function}){const[creating,setCreating]=useState(false);const[query,setQuery]=useState('');const filtered=data.customers.filter(c=>[c.name,c.email??'',c.phone??'',c.contactPerson??''].join(' ').toLowerCase().includes(query.toLowerCase()));return <><div className="toolbar customer-toolbar"><p className="muted">Manage customer relationships, GST details, payment terms, and receivables from one clean workspace.</p><button className="button primary" onClick={()=>setCreating(true)}><Plus/>Add Customer</button></div><div className="metric-grid three"><Metric label="Total Customers" value={String(data.customers.length)} note="Customer records"/><Metric label="Business Customers" value={String(data.customers.filter(c=>c.customerType.toLowerCase().includes('business')).length)} note="Company accounts"/><Metric label="GST Registered" value={String(data.customers.filter(c=>c.gstin).length)} note="Customers with GSTIN"/></div><Panel title="Customer records"><div className="search full-search"><Search/><input placeholder="Search by name, email, phone, or contact person..." value={query} onChange={e=>setQuery(e.target.value)}/></div>{filtered.length?<div className="table-wrap"><table><thead><tr><th>Customer</th><th>Contact</th><th>GSTIN</th><th>Terms</th><th>Recent quotes</th><th>Status</th><th/></tr></thead><tbody>{filtered.map(c=><tr key={c.id}><td><b>{c.name}</b><small>{c.customerType} · {c.region}</small></td><td>{c.contactPerson??'—'}<small>{[c.email,c.phone].filter(Boolean).join(' · ')||'No contact added'}</small></td><td>{c.gstin||'—'}</td><td>{c.paymentTerms} days</td><td>{data.quotes.filter(q=>q.customer===c.name).length}</td><td><Status value={c.active?'ACTIVE':'DISABLED'}/></td><td><button onClick={()=>open('customer',c.id)}>Open <ChevronRight/></button></td></tr>)}</tbody></table></div>:<div className="customer-empty"><UserRound/><h3>No customers found</h3><p>Add your first customer to get started.</p></div>}</Panel>{creating&&<CustomerModal mutate={mutate} close={()=>setCreating(false)}/>}</>}
function CustomerDetail({customer,open,mutate}:{customer?:Customer;open:(v:View,id?:string)=>void;mutate:Function}){const[tier,setTier]=useState(customer?.tier??'Gold');const[terms,setTerms]=useState(customer?.paymentTerms??7);const[active,setActive]=useState(customer?.active??true);useEffect(()=>{setTier(customer?.tier??'Gold');setTerms(customer?.paymentTerms??7);setActive(customer?.active??true)},[customer?.id]);if(!customer)return <Empty text="No customer selected."/>;return <><div className="detail-head"><div><span className="status">{customer.active?'Active':'Disabled'}</span><h2>{customer.name}</h2><p>{customer.customerType} · {customer.region} · {customer.currency}</p></div><button className="button primary" onClick={()=>mutate(`/customers/${customer.id}`,{tier,paymentTerms:terms,active},'PATCH','Customer updated')}>Save customer</button></div><div className="two-col"><Panel title="Customer profile"><div className="form"><label>Tier<select value={tier} onChange={e=>setTier(e.target.value)}><option>Gold</option><option>Silver</option><option>Bronze</option><option>Enterprise</option></select></label><label>Payment terms<input type="number" min="0" max="180" value={terms} onChange={e=>setTerms(Number(e.target.value))}/></label><label className="checkbox-row"><input type="checkbox" checked={active} onChange={e=>setActive(e.target.checked)}/> Customer active</label><div className="facts"><div><span>Contact person</span><b>{customer.contactPerson||'Not added'}</b></div><div><span>Email</span><b>{customer.email||'Not added'}</b></div><div><span>Phone</span><b>{customer.phone?`${customer.countryCode} ${customer.phone}`:'Not added'}</b></div><div><span>GSTIN</span><b>{customer.gstin||'Not added'}</b></div></div></div></Panel><Panel title="Recent activity"><div className="customer-activity">{(customer.quotes??[]).map(q=><button key={q.id} onClick={()=>open('quote',q.id)}><FileCheck/><span><b>{q.number}</b><small>{label(q.stage)} · {money(q.total)}</small></span><ChevronRight/></button>)}{(customer.invoices??[]).map(i=><button key={i.id} onClick={()=>open('invoice',i.id)}><Receipt/><span><b>{i.number}</b><small>{label(i.state)} · {money(i.amount)}</small></span><ChevronRight/></button>)}</div></Panel></div></>}
function CustomerPortal({data,mutate,reload,logout}:{data:Workspace;mutate:Function;reload:()=>Promise<void>;logout:()=>Promise<void>}){type PortalView='dashboard'|'invoices'|'quotations'|'orders'|'history';const[active,setActive]=useState<PortalView>('dashboard');const customer={name:data.user.name,email:data.user.email,organization:{name:data.organization?.name??'DealOS'}};const pendingInvoices=data.invoices.filter(i=>i.state!=='PAID');const pendingQuotes=data.quotes.filter(q=>['APPROVED','NEGOTIATION'].includes(q.stage));const portalNav:Array<[PortalView,string,typeof LayoutDashboard,number|null]>=[['dashboard','Dashboard',LayoutDashboard,null],['invoices','Invoices',FileText,pendingInvoices.length],['quotations','Quotations',FileCheck,pendingQuotes.length],['orders','Purchase Orders',ShoppingCart,null],['history','Purchase History',History,null]];const content=active==='dashboard'?<PortalDashboard customer={customer} invoices={data.invoices} quotes={data.quotes}/>:active==='invoices'?<PortalInvoices invoices={data.invoices} mutate={mutate}/>:active==='quotations'?<PortalQuotations quotes={data.quotes} mutate={mutate}/>:active==='orders'?<PortalOrders quotes={data.quotes}/>:<PortalHistory invoices={data.invoices} quotes={data.quotes}/>;return <div className="customer-portal-shell"><header className="customer-portal-top"><button className="portal-menu" aria-label="Open portal menu"><Menu/></button><div className="brand"><span>D</span><strong>{customer.organization.name}</strong><small>Customer Portal</small></div><div className="header-actions"><button className="icon-button" onClick={reload} aria-label="Reload portal"><RefreshCw/></button><button className="icon-button" aria-label="Notifications"><Bell/>{pendingInvoices.length+pendingQuotes.length>0&&<em>{pendingInvoices.length+pendingQuotes.length}</em>}</button><div className="portal-user"><span>{customer.name[0]}</span><b>{customer.name}</b></div><button className="button ghost" onClick={logout}><LogOut/>Logout</button></div></header><div className="customer-portal-body"><aside className="customer-portal-nav">{portalNav.map(([id,text,Icon,badge])=><button key={id} className={active===id?'active':''} onClick={()=>setActive(id)}><Icon/><span>{text}</span>{Number(badge)>0&&<em>{badge}</em>}</button>)}</aside><div className="customer-portal-content">{content}</div></div></div>}
function PortalDashboard({customer,invoices,quotes}:{customer:{name:string;email:string;organization:{name:string}};invoices:Invoice[];quotes:Quote[]}){const outstanding=invoices.reduce((s,i)=>s+Number(i.amount)-Number(i.paidAmount),0);return <><div className="portal-welcome"><div><h2>Welcome back, {customer.name}</h2><p>Manage invoices, quotations, orders, and purchase history from your portal.</p></div><span className="status active">Active</span></div><div className="metric-grid four portal-metrics"><Metric label="Total invoices" value={String(invoices.length)} note="Shared by the organization"/><Metric label="Pending action" value={String(invoices.filter(i=>i.state==='UNPAID').length+quotes.filter(q=>q.stage==='APPROVED').length)} note="Awaiting your response" tone="warn"/><Metric label="Outstanding balance" value={money(outstanding)} note="Accepted and unpaid"/><Metric label="Total quotations" value={String(quotes.length)} note="Pending and historical"/></div><Panel title="Account information"><div className="portal-account-grid"><div><span>Organization</span><b>{customer.organization.name}</b></div><div><span>Your name</span><b>{customer.name}</b></div><div><span>Email</span><b>{customer.email}</b></div><div><span>Account status</span><b className="good">Active</b></div></div></Panel></>}
function PortalInvoices({invoices,mutate}:{invoices:Invoice[];mutate:Function}){const[tab,setTab]=useState<'pending'|'due'|'history'>('pending');const[requesting,setRequesting]=useState<Invoice|null>(null);const filtered=invoices.filter(i=>tab==='history'?i.state==='PAID':tab==='due'?['UNPAID','PARTIAL'].includes(i.state):i.state==='UNPAID');return <><PortalSectionTitle title="Invoices" note="Manage and respond to your invoices." tabs={[['pending','Pending'],['due','Due'],['history','History']]} active={tab} setActive={setTab}/><div className="portal-list">{filtered.length?filtered.map(i=><article key={i.id}><div><span className="status warning">{label(i.state)}</span><h3>{i.number}</h3><p>{i.customer} · Due {date(i.dueAt)}</p></div><strong>{money(i.amount)}</strong><div className="actions"><button className="button ghost" onClick={()=>setRequesting(i)}><CalendarClock/>Request date</button><button className="button primary" disabled={i.state==='PAID'} onClick={()=>mutate(`/portal/invoices/${i.id}/pay`,{},'POST','Payment recorded')}>Pay now</button></div></article>):<Empty text="No invoices in this category."/>}</div>{requesting&&<Modal title="Request due date change" close={()=>setRequesting(null)}><form className="form" onSubmit={e=>{e.preventDefault();const f=new FormData(e.currentTarget);mutate(`/portal/invoices/${requesting.id}/request-change`,{requestedDate:f.get('date'),message:f.get('message')},'POST','Request sent');setRequesting(null)}}><label>Requested date<input name="date" type="date" required/></label><label>Reason<textarea name="message" required placeholder="Tell the finance team why you need a change."/></label><button className="button primary">Submit request</button></form></Modal>}</>}
function PortalQuotations({quotes,mutate}:{quotes:Quote[];mutate:Function}){const[tab,setTab]=useState<'pending'|'history'>('pending');const[declining,setDeclining]=useState<Quote|null>(null);const filtered=quotes.filter(q=>tab==='pending'?['APPROVED','NEGOTIATION'].includes(q.stage):['CONFIRMED','REJECTED'].includes(q.stage));return <><PortalSectionTitle title="Quotations" note="Review and respond to quotations." tabs={[['pending','Pending'],['history','History']]} active={tab} setActive={setTab}/><div className="portal-list">{filtered.length?filtered.map(q=><article key={q.id}><div><span className="status warning">{label(q.stage)}</span><h3>{q.number}</h3><p>{q.lines.length} item(s) · Version {q.version}</p></div><strong>{money(q.total)}</strong><div className="actions"><button className="button ghost" onClick={()=>setDeclining(q)}><ThumbsDown/>Decline</button><button className="button primary" disabled={q.stage!=='APPROVED'} onClick={()=>mutate(`/portal/quotations/${q.id}/confirm`,{},'POST','Quotation confirmed')}>Accept quotation</button></div></article>):<Empty text="No quotations in this category."/>}</div>{declining&&<Modal title={`Decline ${declining.number}`} close={()=>setDeclining(null)}><form className="form" onSubmit={e=>{e.preventDefault();const f=new FormData(e.currentTarget);mutate(`/portal/quotations/${declining.id}/message`,{message:`Declined: ${f.get('reason')}`},'POST','Decline note sent');setDeclining(null)}}><label>Reason<textarea name="reason" required placeholder="Share the reason for declining."/></label><button className="button danger">Send decline note</button></form></Modal>}</>}
function PortalOrders({quotes}:{quotes:Quote[]}){const orders=quotes.filter(q=>q.stage==='CONFIRMED');return <><PortalSectionTitle title="Purchase Orders" note="Confirmed quotations converted into orders."/><div className="portal-list">{orders.length?orders.map(q=><article key={q.id}><div><span className="status active">Confirmed</span><h3>SO-{q.number.replace(/^Q-/,'')}</h3><p>{q.customer} · {q.lines.length} line(s)</p></div><strong>{money(q.total)}</strong></article>):<Empty text="No purchase orders yet."/>}</div></>}
function PortalHistory({invoices,quotes}:{invoices:Invoice[];quotes:Quote[]}){return <><PortalSectionTitle title="Purchase History" note="A compact history of invoices and completed quotations."/><div className="customer-activity history-list">{invoices.map(i=><button key={i.id}><Receipt/><span><b>{i.number}</b><small>{label(i.state)} · {money(i.amount)}</small></span></button>)}{quotes.filter(q=>q.stage==='CONFIRMED').map(q=><button key={q.id}><FileCheck/><span><b>{q.number}</b><small>{money(q.total)}</small></span></button>)}</div></>}
function PortalSectionTitle({title:txt,note,tabs,active,setActive}:{title:string;note:string;tabs?:Array<[string,string]>;active?:string;setActive?:(v:any)=>void}){return <div className="portal-section-title"><div><h2>{txt}</h2><p>{note}</p></div>{tabs&&<div className="filter-row">{tabs.map(([id,text])=><button key={id} className={`chip ${active===id?'active':''}`} onClick={()=>setActive?.(id)}>{text}</button>)}</div>}</div>}

type CustomerPortalView='quotations'|'invoices'|'messages'|'profile';
function CustomerPortalV2({data,mutate,reload,logout}:{data:Workspace;mutate:Function;reload:()=>Promise<void>;logout:()=>Promise<void>}){const[active,setActive]=useState<CustomerPortalView>('quotations');const pendingQuotes=data.quotes.filter(q=>['APPROVED','NEGOTIATION'].includes(q.stage)).length;const openInvoices=data.invoices.filter(i=>i.state!=='PAID').length;const messages=data.quotes.reduce((sum,q)=>sum+q.negotiation.length,0);const tabs:Array<[CustomerPortalView,string,ReactNode,number]>=[['quotations','My quotations',<FileCheck/>,pendingQuotes],['invoices','Invoices',<Receipt/>,openInvoices],['messages','Messages',<MessageSquare/>,messages],['profile','Profile',<UserRound/>,0]];return <div className="deal-room"><header className="deal-room-header"><div className="deal-room-brand"><Brand/><span>Customer portal</span></div><div className="deal-room-user"><span>{data.user.name.slice(0,1).toUpperCase()}</span><div><b>{data.user.name}</b><small>{data.user.email}</small></div><button className="icon-button" onClick={reload} aria-label="Refresh customer portal"><RefreshCw/></button><button className="icon-button" onClick={logout} aria-label="Sign out"><LogOut/></button></div></header><nav className="deal-room-tabs" aria-label="Customer portal">{tabs.map(([id,text,icon,count])=><button key={id} className={active===id?'active':''} onClick={()=>setActive(id)}>{icon}<span>{text}</span>{count>0&&<em>{count}</em>}</button>)}</nav><main className="deal-room-main"><div className="deal-room-intro"><div><span className="eyebrow">Secure deal room</span><h1>{active==='quotations'?'Review your quotations':active==='invoices'?'Your invoices':active==='messages'?'Commercial conversation':'Your portal profile'}</h1><p>{active==='quotations'?'Review terms, request a change, or accept the latest approved quotation.':active==='invoices'?'Every invoice shared with your invited email appears here automatically.':active==='messages'?'All quotation comments and negotiation updates stay synchronized here.':'This verified identity controls which documents you can access.'}</p></div><span className="portal-sync"><i/>Live sync</span></div>{active==='quotations'?<CustomerQuoteRoom quotes={data.quotes} mutate={mutate}/>:active==='invoices'?<CustomerInvoiceRoom invoices={data.invoices} mutate={mutate}/>:active==='messages'?<CustomerMessages quotes={data.quotes}/>:<CustomerProfile data={data}/>}</main></div>}

function CustomerQuoteRoom({quotes,mutate}:{quotes:Quote[];mutate:Function}){const[selectedId,setSelectedId]=useState(quotes[0]?.id??'');const[message,setMessage]=useState('');const[counter,setCounter]=useState(0);const[delivery,setDelivery]=useState('');useEffect(()=>{if(!quotes.some(q=>q.id===selectedId))setSelectedId(quotes[0]?.id??'')},[quotes,selectedId]);const quote=quotes.find(q=>q.id===selectedId);if(!quote)return <div className="deal-room-empty"><FileCheck/><h2>No quotations yet</h2><p>Approved quotations sent to your invited email will appear here.</p></div>;const submit=()=>{const detail=[message.trim(),delivery?`Requested delivery date: ${delivery}`:''].filter(Boolean).join(' · ');mutate(`/portal/quotations/${quote.id}/message`,counter>0?{message:detail,counterDiscount:counter}:{message:detail},'POST',counter>0?'Counter proposal sent':'Request sent');setMessage('');setCounter(0);setDelivery('')};return <div className="quote-room-layout"><aside className="document-list">{quotes.map(item=><button key={item.id} className={item.id===quote.id?'active':''} onClick={()=>setSelectedId(item.id)}><span><small>{item.number}</small><b>{item.customer}</b></span><strong>{money(item.total)}</strong><em>{label(item.stage)}</em></button>)}</aside><section className="quotation-sheet"><div className="quotation-sheet-head"><div><span className={`status ${quote.stage.toLowerCase()}`}>{label(quote.stage)}</span><h2>{quote.number}</h2><p>Revision {quote.version} · Shared by {quote.customer}</p></div><strong>{money(quote.total)}</strong></div><div className="quotation-lines"><table><thead><tr><th>Line</th><th>Qty</th><th>Unit price</th><th>Discount</th><th>Amount</th></tr></thead><tbody>{quote.lines.map(line=><tr key={line.id}><td><b>{line.product.name}</b><small>{line.product.description}</small></td><td>{line.quantity}</td><td>{money(line.unitPrice)}</td><td>{line.discount}%</td><td>{money(Number(line.unitPrice)*line.quantity*(1-Number(line.discount)/100))}</td></tr>)}</tbody></table></div><div className="negotiation-grid"><label>Your comment<textarea value={message} onChange={e=>setMessage(e.target.value)} placeholder="Ask about a line or explain the requested change"/></label><label>Counter discount %<input type="number" min="0" max="100" value={counter} onChange={e=>setCounter(Number(e.target.value))}/></label><label>Requested delivery date<input type="date" value={delivery} onChange={e=>setDelivery(e.target.value)}/></label></div><div className="quotation-actions"><button className="button ghost" disabled={!message.trim()&&!delivery} onClick={submit}><Send/>Submit request</button><button className="button primary accept-button" disabled={quote.stage!=='APPROVED'} onClick={()=>mutate(`/portal/quotations/${quote.id}/confirm`,{},'POST','Quotation accepted')}><Check/>Accept quotation</button></div>{quote.stage!=='APPROVED'&&<div className="approval-note"><ShieldCheck/><span><b>Approval in progress</b>Acceptance becomes available when the latest terms are approved and re-shared.</span></div>}{quote.negotiation.length>0&&<div className="conversation-strip"><h3>Conversation</h3>{quote.negotiation.map(item=><div key={item.id}><span>{item.author.slice(0,1)}</span><p><b>{item.author}</b>{item.message}<small>{date(item.createdAt)}{item.counterDiscount?` · ${item.counterDiscount}% proposed`:''}</small></p></div>)}</div>}</section></div>}

function CustomerInvoiceRoom({invoices,mutate}:{invoices:Invoice[];mutate:Function}){const[selectedId,setSelectedId]=useState(invoices[0]?.id??'');const[requestOpen,setRequestOpen]=useState(false);const invoice=invoices.find(i=>i.id===selectedId)??invoices[0];if(!invoice)return <div className="deal-room-empty"><Receipt/><h2>No invoices yet</h2><p>Invoices created for your invited email will appear here automatically.</p></div>;return <div className="quote-room-layout"><aside className="document-list">{invoices.map(item=><button key={item.id} className={item.id===invoice.id?'active':''} onClick={()=>setSelectedId(item.id)}><span><small>{item.number}</small><b>Due {date(item.dueAt)}</b></span><strong>{money(item.amount)}</strong><em>{label(item.state)}</em></button>)}</aside><section className="quotation-sheet invoice-sheet"><div className="quotation-sheet-head"><div><span className={`status ${invoice.state.toLowerCase()}`}>{label(invoice.state)}</span><h2>{invoice.number}</h2><p>Issued to {invoice.customer} · Due {date(invoice.dueAt)}</p></div><strong>{money(invoice.amount)}</strong></div><div className="quotation-lines"><table><thead><tr><th>Description</th><th>Qty</th><th>Net</th><th>Tax</th><th>Amount</th></tr></thead><tbody>{invoice.lines.map((line,index)=><tr key={`${line.description}-${index}`}><td><b>{line.description}</b><small>{line.cadence??'One-time'}</small></td><td>{line.quantity??1}</td><td>{money(line.net??line.amount)}</td><td>{money(line.tax??0)}</td><td>{money(line.amount)}</td></tr>)}</tbody></table></div><div className="invoice-summary"><span>Invoice total<b>{money(invoice.amount)}</b></span><span>Paid<b>{money(invoice.paidAmount)}</b></span><span>Outstanding<b>{money(Number(invoice.amount)-Number(invoice.paidAmount))}</b></span></div><div className="quotation-actions"><a className="button ghost" href={`/api/v1/invoices/${invoice.id}/pdf`} download><Download/>Download PDF</a><button className="button primary" disabled={invoice.state==='PAID'} onClick={()=>setRequestOpen(true)}><CalendarClock/>Request due-date change</button></div></section>{requestOpen&&<Modal title="Request due-date change" close={()=>setRequestOpen(false)}><form className="form" onSubmit={e=>{e.preventDefault();const form=new FormData(e.currentTarget);mutate(`/portal/invoices/${invoice.id}/request-change`,{requestedDate:form.get('date'),message:form.get('message')},'POST','Request sent');setRequestOpen(false)}}><label>Requested date<input name="date" type="date" required/></label><label>Reason<textarea name="message" required placeholder="Explain the requested change"/></label><button className="button primary">Submit request</button></form></Modal>}</div>}

function CustomerMessages({quotes}:{quotes:Quote[]}){const messages=quotes.flatMap(quote=>quote.negotiation.map(item=>({...item,quoteNumber:quote.number}))).sort((a,b)=>new Date(b.createdAt).getTime()-new Date(a.createdAt).getTime());return <section className="messages-panel">{messages.length?messages.map(item=><article key={item.id}><span>{item.author.slice(0,1).toUpperCase()}</span><div><small>{item.quoteNumber} · {date(item.createdAt)}</small><h3>{item.author}</h3><p>{item.message}</p>{item.counterDiscount&&<em>Counter proposal: {item.counterDiscount}%</em>}</div></article>):<div className="deal-room-empty"><MessageSquare/><h2>No messages yet</h2><p>Your quotation conversations will be collected here.</p></div>}</section>}

function CustomerProfile({data}:{data:Workspace}){return <section className="profile-card"><div className="profile-avatar">{data.user.name.slice(0,1).toUpperCase()}</div><div><span className="status active"><Check/>Verified customer</span><h2>{data.user.name}</h2><p>{data.user.email}</p></div><dl><div><dt>Organization</dt><dd>{data.organization?.name}</dd></div><div><dt>Portal access</dt><dd>Google verified</dd></div><div><dt>Quotations shared</dt><dd>{data.quotes.length}</dd></div><div><dt>Invoices shared</dt><dd>{data.invoices.length}</dd></div></dl><div className="approval-note"><ShieldCheck/><span><b>Your data is isolated</b>Only records assigned to this customer identity and organization are returned by the server.</span></div></section>}
function CustomerModal({mutate,close,onSaved}:{mutate:Function;close:()=>void;onSaved?:()=>void}){const[same,setSame]=useState(true);const submit=async(e:FormEvent<HTMLFormElement>)=>{e.preventDefault();const f=new FormData(e.currentTarget);const billingAddress=String(f.get('billingAddress')??'');await mutate('/customers',{customerType:f.get('customerType'),region:f.get('region'),name:f.get('name'),contactPerson:f.get('contactPerson')||null,email:f.get('email')||null,countryCode:f.get('countryCode'),phone:f.get('phone')||null,gstin:f.get('gstin')||null,billingAddress:billingAddress||null,shippingAddress:same?billingAddress:String(f.get('shippingAddress')??'')||null,paymentTerms:Number(f.get('paymentTerms')),tier:f.get('tier'),currency:f.get('currency'),active:true},'POST','Customer created');onSaved?.();close()};return <div className="modal-wrap" onMouseDown={e=>e.target===e.currentTarget&&close()}><div className="modal large-modal"><div className="panel-title"><h3><UserRound/> Add New Customer</h3><button onClick={close}><X/></button></div><form className="form customer-form" onSubmit={submit}><label>Customer Type *<select name="customerType" defaultValue="Business / Company"><option>Business / Company</option><option>Individual</option></select></label><label>GSTIN (Optional)<input name="gstin" placeholder="e.g., 22AAAAA0000A1Z5" maxLength={15}/><small>Must be 15 characters, as per GST format.</small></label><label>Customer Region / Country<select name="region" defaultValue="India"><option>India</option><option>United States</option><option>United Kingdom</option><option>Singapore</option><option>United Arab Emirates</option></select><small>Affects phone country code and tax fields for this customer.</small></label><label>Tier<select name="tier" defaultValue="Gold"><option>Gold</option><option>Silver</option><option>Bronze</option><option>Enterprise</option></select></label><label>Company Name *<input name="name" required placeholder="Enter company name"/></label><label>Contact Person<input name="contactPerson" placeholder="Enter contact person name"/></label><label>Email ID<input name="email" type="email" placeholder="contact@example.com"/><small>Used as the customer portal identity and invoice receipt destination.</small></label><label>Phone Number *<div className="phone-row"><select name="countryCode" defaultValue="+91"><option>+91</option><option>+1</option><option>+44</option><option>+65</option><option>+971</option></select><input name="phone" required placeholder="e.g. 9876543210"/></div><small>Max 10 digits for selected country.</small></label><div className="wide form-section-title">Address</div><label>Billing Address<textarea name="billingAddress" placeholder="Click to add billing address..."/></label><label>Shipping Address <span className="inline-check"><input type="checkbox" checked={same} onChange={e=>setSame(e.target.checked)}/> Same as billing</span><textarea name="shippingAddress" placeholder="Click to add shipping address..." disabled={same}/></label><label>Payment Terms (Days)<select name="paymentTerms" defaultValue="7"><option value="7">7 Days</option><option value="15">15 Days</option><option value="30">30 Days</option><option value="45">45 Days</option><option value="60">60 Days</option></select></label><label>Currency<input name="currency" defaultValue="INR" maxLength={3}/></label><div className="actions wide form-footer"><button type="button" className="button ghost" onClick={close}><X/>Cancel</button><button className="button primary"><Check/>Add Customer</button></div></form></div></div>}
function CreateProductModal({mutate,close}:{mutate:Function;close:()=>void}){const[recurring,setRecurring]=useState(false);const[price,setPrice]=useState(0);const[cost,setCost]=useState(0);const[taxRate,setTaxRate]=useState(18);const[openingStock,setOpeningStock]=useState(10);const[minAlertLevel,setMinAlertLevel]=useState(5);const[maxCapacity,setMaxCapacity]=useState(1000);const[active,setActive]=useState(true);const[storeVisible,setStoreVisible]=useState(true);const[featured,setFeatured]=useState(false);const final=price+(price*taxRate/100);const margin=price-cost;const sku=()=>`SKU-${Math.floor(100000+Math.random()*900000)}`;const submit=async(e:FormEvent<HTMLFormElement>)=>{e.preventDefault();const f=new FormData(e.currentTarget);await mutate('/products',{name:f.get('name'),sku:f.get('sku'),category:f.get('category'),description:f.get('description'),unit:f.get('unit'),price,cost,taxRate,recurring,cadence:recurring?f.get('cadence'):null,active,storeVisible,featured,openingStock,minAlertLevel,maxCapacity},'POST','Product added to catalog');close()};return <Modal title="Create Product" close={close}><form className="add-product-form refined-product-form" onSubmit={submit}><div className="product-form-head"><span><PackagePlus/></span><div><h3>Create Product</h3><p>Save one catalog item for invoices, quotations, stock, and customer documents.</p></div><label className="checkbox-row service-toggle"><input type="checkbox" checked={recurring} onChange={e=>setRecurring(e.target.checked)}/> Service product</label></div><div className="product-create-grid"><section className="product-form-card product-main-card"><h4>Product Details</h4><div className="form grid"><label>Product Name *<input name="name" required placeholder="Enter product name"/></label><label>SKU / HSN Code *<input name="sku" required defaultValue={sku()} placeholder="SKU or HSN code"/></label><label className="wide">Description<textarea name="description" placeholder="Product description" defaultValue="Sellable catalog item."/></label><label>Category<select name="category"><option>Hardware</option><option>Services</option><option>Subscriptions</option><option>Other</option></select></label><label>Unit<select name="unit" defaultValue="Piece"><option>Piece</option><option>Unit</option><option>Hour</option><option>Month</option><option>License</option></select></label><label>Vendor / Brand<input name="brand" placeholder="Optional"/></label><label>Cadence<select name="cadence" disabled={!recurring}><option>Monthly</option><option>Quarterly</option><option>Yearly</option></select></label></div></section><aside className="product-summary-card"><h4>Price Preview</h4><strong>{money(final)}</strong><span>Customer price including GST</span><div><small>Base price</small><b>{money(price)}</b></div><div><small>GST amount</small><b>{money(final-price)}</b></div><div><small>Margin</small><b className={margin<0?'loss':''}>{money(margin)}</b></div></aside><section className="product-form-card"><h4>Pricing</h4><div className="form grid"><label>Price Type<select><option>GST Excluded</option><option>GST Included</option></select></label><label>GST Rate<select value={taxRate} onChange={e=>setTaxRate(Number(e.target.value))}><option value={0}>0%</option><option value={5}>5%</option><option value={12}>12%</option><option value={18}>18%</option><option value={28}>28%</option></select></label><label>Purchase Price<input type="number" min="0" value={cost} onChange={e=>setCost(Number(e.target.value))}/></label><label>Selling Price *<input type="number" min="0" required value={price} onChange={e=>setPrice(Number(e.target.value))}/></label></div></section><section className="product-form-card"><h4>Stock Thresholds</h4><div className="form grid three-field"><label>Opening Stock *<input type="number" min="0" required value={openingStock} onChange={e=>setOpeningStock(Number(e.target.value))}/></label><label>Min Alert Level<input type="number" min="0" value={minAlertLevel} onChange={e=>setMinAlertLevel(Number(e.target.value))}/></label><label>Max Capacity<input type="number" min="1" value={maxCapacity} onChange={e=>setMaxCapacity(Number(e.target.value))}/></label></div></section><section className="product-form-card product-visibility-card"><h4>Availability</h4><div className="visibility-grid"><ToggleField title="Active Status" note="Available in admin lists" checked={active} setChecked={setActive}/><ToggleField title="Store Visibility" note="Visible in POS or online sales" checked={storeVisible} setChecked={setStoreVisible}/><ToggleField title="Featured" note="Highlight this catalog item" checked={featured} setChecked={setFeatured}/></div></section></div><div className="actions product-form-actions"><button type="button" className="button ghost" onClick={close}>Cancel</button><button className="button primary"><PackagePlus/>Create Product</button></div></form></Modal>}
function ToggleField({title,note,checked,setChecked}:{title:string;note:string;checked:boolean;setChecked:(checked:boolean)=>void}){return <label className="toggle-field"><span><b>{title}</b><small>{note}</small></span><input type="checkbox" checked={checked} onChange={e=>setChecked(e.target.checked)}/><i/></label>}
function AddInvoiceItemsModal({products,lines,setLines,mutate,close}:{products:Product[];lines:CommerceLine[];setLines:(fn:(value:CommerceLine[])=>CommerceLine[])=>void;mutate:Function;close:()=>void}){const[query,setQuery]=useState('');const[creating,setCreating]=useState(false);const active=products.filter(p=>p.active);const filtered=active.filter(p=>[p.name,p.sku,p.category,p.description].join(' ').toLowerCase().includes(query.toLowerCase()));const update=(productId:string,quantity:number)=>setLines(value=>{const existing=value.find(line=>line.productId===productId);if(quantity<=0)return value.filter(line=>line.productId!==productId);if(existing)return value.map(line=>line.productId===productId?{...line,quantity}:line);return [...value,{productId,quantity,discount:0}]});return <div className="modal-wrap" onMouseDown={e=>e.target===e.currentTarget&&close()}><div className="modal add-items-modal"><div className="panel-title"><h3>Add Items</h3><button onClick={close}><X/></button></div><div className="add-items-toolbar"><div className="search"><Search/><input autoFocus placeholder="Search items by name, SKU, or category" value={query} onChange={e=>setQuery(e.target.value)}/></div><button className="button primary" type="button" onClick={()=>setCreating(true)}><Plus/>Create New Product</button></div><div className="table-wrap item-picker-table"><table><thead><tr><th>Item name</th><th>SKU code</th><th>Category</th><th>Sales price</th><th>Stock</th><th>Quantity</th></tr></thead><tbody>{filtered.map(product=>{const selected=lines.find(line=>line.productId===product.id);const stock=product.stocks.reduce((sum,row)=>sum+row.onHand-row.reserved,0);return <tr key={product.id}><td><b>{product.name}</b><small>{product.description}</small></td><td>{product.sku}</td><td>{product.category}</td><td>{money(product.price)}</td><td>{product.recurring?'Service':stock}</td><td><input className="qty-input" type="number" min="0" value={selected?.quantity??0} onChange={e=>update(product.id,Number(e.target.value))}/></td></tr>})}</tbody></table>{!filtered.length&&<Empty text="No items found. Create a new product to add it to this invoice."/>}</div><div className="actions add-items-actions"><button type="button" className="button ghost" onClick={close}>Cancel</button><button type="button" className="button primary" onClick={close}>Done</button></div>{creating&&<CreateProductModal mutate={mutate} close={()=>setCreating(false)}/>}</div></div>}
function CustomerPickerModal({customers,selectedId,onSelect,onCreate,close}:{customers:Customer[];selectedId:string;onSelect:(customer:Customer|null)=>void;onCreate:()=>void;close:()=>void}){const[query,setQuery]=useState('');const filtered=customers.filter(c=>[c.name,c.contactPerson??'',c.phone??'',c.email??'',c.gstin??''].join(' ').toLowerCase().includes(query.toLowerCase()));return <div className="customer-picker-popover"><div className="customer-picker-head"><span>Select Party</span><button type="button" onClick={close}>Cancel</button></div><div className="customer-picker-search"><Search/><input autoFocus placeholder="Search by name, phone, email, GST or network ID..." value={query} onChange={e=>setQuery(e.target.value)}/></div><div className="customer-picker-list"><small>Customers</small><button type="button" className={`customer-picker-row cash ${!selectedId?'active':''}`} onClick={()=>{onSelect(null);close()}}><i><IndianRupee/></i><span><b>Cash Sale / Counter Sale</b><em>Quick walk-in / counter sale without phone number</em></span><strong>Cash</strong><Plus/></button>{filtered.map(customer=><button type="button" key={customer.id} className={`customer-picker-row ${selectedId===customer.id?'active':''}`} onClick={()=>{onSelect(customer);close()}}><i><UserRound/></i><span><b>{customer.name}</b><em>{[customer.email,customer.phone?`${customer.countryCode} ${customer.phone}`:null,customer.gstin].filter(Boolean).join(' · ')||customer.customerType}</em></span><strong>{customer.tier}</strong><Plus/></button>)}{!filtered.length&&<p>No customers found</p>}</div><button type="button" className="customer-picker-create" onClick={onCreate}><Plus/>Create Customer</button></div>}
function CreateInvoiceModal({data,mutate,close}:{data:Workspace;mutate:Function;close:()=>void}){const activeCustomers=data.customers.filter(c=>c.active);const termsDueDate=(days:number)=>new Date(Date.now()+days*86400000).toISOString().slice(0,10);const[customerId,setCustomerId]=useState('');const[terms,setTerms]=useState(30);const[dueAt,setDueAt]=useState(termsDueDate(30));const[lines,setLines]=useState<CommerceLine[]>([]);const[adding,setAdding]=useState(false);const[pickingCustomer,setPickingCustomer]=useState(true);const[creatingCustomer,setCreatingCustomer]=useState(false);const[pickNewest,setPickNewest]=useState(false);const[sendReceipt,setSendReceipt]=useState(true);const invoiceDate=new Date().toISOString().slice(0,10);const customer=activeCustomers.find(c=>c.id===customerId);const selectCustomer=(next:Customer|null)=>{setCustomerId(next?.id??'');applyTerms(next?.paymentTerms??30)};const applyTerms=(days:number)=>{setTerms(days);setDueAt(termsDueDate(days))};useEffect(()=>{if(!pickNewest)return;const newest=[...activeCustomers].sort((a,b)=>new Date(b.createdAt).getTime()-new Date(a.createdAt).getTime())[0];if(newest){selectCustomer(newest);setPickingCustomer(false)}setPickNewest(false)},[data.customers.length,pickNewest]);const updateLine=(index:number,patch:Partial<CommerceLine>)=>setLines(value=>value.map((line,i)=>i===index?{...line,...patch}:line));const removeLine=(index:number)=>setLines(value=>value.filter((_,i)=>i!==index));const subtotal=lines.reduce((sum,line)=>sum+lineAmount(data.products.find(p=>p.id===line.productId),line).net,0);const tax=lines.reduce((sum,line)=>sum+lineAmount(data.products.find(p=>p.id===line.productId),line).tax,0);const total=subtotal+tax;const partyName=customer?.name??'Cash Sale';const partyNote=customer?(customer.contactPerson||customer.customerType):'Counter Sale / Walk-in Customer';const submit=async(e:FormEvent<HTMLFormElement>)=>{e.preventDefault();await mutate('/invoices',{customerId,dueAt:String(new FormData(e.currentTarget).get('dueAt')),lines,sendReceipt},'POST',sendReceipt?'Invoice created and receipt email queued':'Invoice created');close()};return <div className="modal-wrap" onMouseDown={e=>e.target===e.currentTarget&&close()}><div className="modal invoice-workspace-modal"><form onSubmit={submit}><div className="invoice-create-head"><div><h3>Create Invoice</h3><p>Build a customer invoice from your synced product catalog.</p></div><div className="actions"><button type="button" className="button ghost">Settings</button><button type="button" className="button ghost" onClick={()=>{setLines([]);selectCustomer(null)}}>Clear Form</button><button type="button" className="button ghost" onClick={close}>Cancel</button><button className="button primary" disabled={!customerId||!lines.length||(sendReceipt&&!customer?.email)}><Receipt/>Create Invoice</button></div></div><div className="invoice-create-grid"><section className="invoice-party-card"><div><span><UserRound/>Bill To</span><button type="button" className="button ghost compact-change" onClick={()=>setPickingCustomer(true)}>{customerId?'Change':'Create Customer'}</button></div><h2>{partyName}</h2><p>{partyNote}</p><div className="contact-card"><span>Name <b>{customer?.contactPerson||customer?.name||'Cash Sale'}</b></span><span>Phone <b>{customer?.phone?`${customer.countryCode} ${customer.phone}`:'--'}</b></span><span>Email ID <b>{customer?.email||'Required for portal and receipt email'}</b></span></div>{pickingCustomer&&<CustomerPickerModal customers={activeCustomers} selectedId={customerId} onSelect={selectCustomer} close={()=>setPickingCustomer(false)} onCreate={()=>setCreatingCustomer(true)}/>}</section><section className="invoice-party-card muted-card"><span><Send/>Ship To</span><h2>{partyName}</h2><p>{customer?.shippingAddress||customer?.billingAddress||partyNote}</p></section><aside className="invoice-side-panel"><label>Invoice Date<input type="date" name="invoiceDate" value={invoiceDate} readOnly/></label><label>Due Date<input type="date" name="dueAt" value={dueAt} onChange={e=>setDueAt(e.target.value)} required/></label><label>Payment Terms<input type="number" min="0" max="180" value={terms} onChange={e=>applyTerms(Number(e.target.value))}/><small>Days</small></label><label className="checkbox-row receipt-toggle"><input type="checkbox" checked={sendReceipt} onChange={e=>setSendReceipt(e.target.checked)}/><Mail/>Send receipt to customer Email ID</label>{sendReceipt&&!customer?.email&&<div className="error"><AlertTriangle/>Add a customer email before sending a receipt.</div>}</aside></div><div className="invoice-item-actions"><button type="button" className="button primary add-item-button" onClick={()=>setAdding(true)}><Plus/>Add Item</button><div className="search"><Search/><input placeholder="Scan barcode or SKU..." readOnly onClick={()=>setAdding(true)}/></div></div><div className="invoice-lines-shell"><table><thead><tr><th>No</th><th>Items</th><th>HSN/SKU</th><th>Qty</th><th>Unit</th><th>Price/Item</th><th>Discount</th><th>Amount</th><th/></tr></thead><tbody>{lines.map((line,index)=>{const product=data.products.find(p=>p.id===line.productId);const amount=lineAmount(product,line);return <tr key={`${line.productId}-${index}`}><td>{index+1}</td><td><b>{product?.name}</b><small>{product?.description}</small></td><td>{product?.sku}</td><td><input className="qty-input" type="number" min="1" value={line.quantity} onChange={e=>updateLine(index,{quantity:Number(e.target.value)})}/></td><td>{product?.unit}</td><td>{money(product?.price??0)}</td><td><input className="qty-input" type="number" min="0" max="100" value={line.discount} onChange={e=>updateLine(index,{discount:Number(e.target.value)})}/></td><td>{money(amount.total)}</td><td><button type="button" className="icon-button" aria-label="Remove item" onClick={()=>removeLine(index)}><Trash2/></button></td></tr>})}</tbody></table>{!lines.length&&<Empty text="No items added yet. Click Add Item to start."/>}</div><div className="invoice-total-bar"><span>Subtotal <b>{money(subtotal)}</b></span><span>GST <b>{money(tax)}</b></span><span>Total <b>{money(total)}</b></span></div></form>{adding&&<AddInvoiceItemsModal products={data.products} lines={lines} setLines={setLines} mutate={mutate} close={()=>setAdding(false)}/>} {creatingCustomer&&<CustomerModal mutate={mutate} close={()=>setCreatingCustomer(false)} onSaved={()=>setPickNewest(true)}/>}</div></div>}
function Policies({data,mutate}:{data:Workspace;mutate:Function}){return <Panel title="Discount tiers and approval chain"><div className="policy-grid">{data.policies.map(p=><PolicyCard key={p.id} policy={p} mutate={mutate}/>)}</div><div className="approval-chain"><div><i>1</i><span><b>Within policy</b><small>No approval required</small></span></div><ChevronRight/><div><i>2</i><span><b>Above line or blended limit</b><small>Sales Manager review</small></span></div><ChevronRight/><div><i>3</i><span><b>High-risk exception</b><small>Finance review after Manager</small></span></div></div></Panel>}
function PolicyCard({policy,mutate}:{policy:Workspace['policies'][number];mutate:Function}){const[max,setMax]=useState(Number(policy.maxDiscount));const[finance,setFinance]=useState(Number(policy.financeThreshold));return <div className="policy-card"><div><span className="tier">{policy.tier}</span><b>Maximum discount</b></div><label><input type="number" min="0" max="100" value={max} onChange={e=>setMax(Number(e.target.value))}/>%</label><div className="facts"><div><span>Hardware</span><b>{policy.hardwareLimit}%</b></div><div><span>Services</span><b>{policy.servicesLimit}%</b></div><div><span>Subscriptions</span><b>{policy.subscriptionLimit}%</b></div></div><label>Finance after <input type="number" min="0" max="100" value={finance} onChange={e=>setFinance(Number(e.target.value))}/> pts</label><button className="button ghost" onClick={()=>mutate(`/policies/${policy.id}`,{maxDiscount:max,financeThreshold:finance},'PATCH','Policy updated')}>Save policy</button></div>}
const accessModules=[['dashboard','Overview'],['quotations','Quotations'],['approvals','Approvals'],['fulfillment','Fulfillment & stock'],['subscriptions','Subscriptions'],['invoices','Invoices'],['health','Deal health'],['reports','Reports'],['products','Products'],['customers','Customers'],['policies','Rules']] as const;
type AccessModuleId = typeof accessModules[number][0];
type ProvisionableRole = 'REP'|'MANAGER'|'FINANCE';
type ManagedRole = ProvisionableRole|'ADMIN';
const rolePresets:Array<{id:ProvisionableRole;label:string;note:string;modules:AccessModuleId[]}>= [
  {id:'REP',label:'Sales representative',note:'Creates quotations, owns customer follow-up, and sees deal health.',modules:['dashboard','quotations','health']},
  {id:'MANAGER',label:'Manager',note:'Reviews commercial exceptions, policies, reports, and team deals.',modules:['dashboard','quotations','approvals','health','reports','policies']},
  {id:'FINANCE',label:'Finance',note:'Handles approval checks, fulfillment, subscriptions, invoices, and reports.',modules:['dashboard','approvals','fulfillment','subscriptions','invoices','reports']},
];
const roleName=(role:string)=>rolePresets.find(r=>r.id===role)?.label??label(role);
const generatedPassword=()=>`Deal-${crypto.getRandomValues(new Uint32Array(2))[0]!.toString(36)}-${crypto.getRandomValues(new Uint32Array(2))[1]!.toString(36)}!`;
function AccessControl({data,reload}:{data:Workspace;reload:()=>Promise<void>}){
  const[name,setName]=useState('');
  const[email,setEmail]=useState('');
  const[password,setPassword]=useState('');
  const[role,setRole]=useState<ProvisionableRole>('REP');
  const[selected,setSelected]=useState<AccessModuleId[]>([...rolePresets[0]!.modules]);
  const[credentials,setCredentials]=useState<{email:string;loginId:string;password:string}|null>(null);
  const[editing,setEditing]=useState<Workspace['users'][number]|null>(null);
  const[busy,setBusy]=useState(false);
  const[error,setError]=useState('');
  const activeRole=rolePresets.find(r=>r.id===role)!;
  const chooseRole=(next:ProvisionableRole)=>{setRole(next);setSelected([...rolePresets.find(r=>r.id===next)!.modules])};
  const toggleModule=(id:AccessModuleId)=>setSelected(selected.includes(id)?selected.filter(x=>x!==id):[...selected,id]);
  const create=async(e:FormEvent)=>{
    e.preventDefault();
    try{
      setBusy(true);setError('');
      const result=await request<{credentials:{email:string;loginId:string;password:string}}>('/admin/users',{method:'POST',body:JSON.stringify({name,email,password,role,moduleAccess:selected})});
      window.sessionStorage.setItem('dealos_generated_login',JSON.stringify(result.credentials));
      setCredentials(result.credentials);
      setName('');setEmail('');setPassword('');
      chooseRole('REP');
      await reload();
    }catch(e){
      setError(e instanceof Error?e.message:'Could not create access');
    }finally{
      setBusy(false);
    }
  };
  return <div className="access-layout"><Panel title={`${data.organization.name} · Add user access`}><form className="access-form" onSubmit={create}><label>User name<input required maxLength={120} value={name} onChange={e=>setName(e.target.value)} placeholder="Jordan Davis"/></label><label>Email ID<input type="email" required value={email} onChange={e=>setEmail(e.target.value)} placeholder="jordan@company.com"/></label><label>Password<div className="password-inline"><input required minLength={12} maxLength={128} value={password} onChange={e=>setPassword(e.target.value)} placeholder="Enter or generate a password"/><button className="button ghost" type="button" onClick={()=>setPassword(generatedPassword())}>Generate password</button></div></label><div><b>Business role</b><p className="muted">Select the user's business role. Organization admin login generation is not available here.</p><div className="role-grid">{rolePresets.map(option=><button type="button" className={role===option.id?'selected':''} key={option.id} onClick={()=>chooseRole(option.id)}><span><ShieldCheck/>{option.label}</span><small>{option.note}</small></button>)}</div></div><div><b>Visible modules</b><p className="muted">Role selection starts with a preset. You can add or remove modules before generating access.</p><div className="module-grid">{accessModules.map(([id,text])=><label className={selected.includes(id)?'selected':'disabled'} key={id}><input type="checkbox" checked={selected.includes(id)} onChange={()=>toggleModule(id)}/><span><Check/>{text}</span></label>)}</div></div>{error&&<div className="error">{error}</div>}<button className="button primary" disabled={busy||!password||!selected.length}><UserRound/> {busy?'Generating...':'Generate login'}</button></form>{credentials&&<div className="credential-card" role="status"><span className="eyebrow">LOGIN READY</span><h3>Credentials generated</h3><div><span>Email ID</span><code>{credentials.email}</code></div><div><span>User ID</span><code>{credentials.loginId}</code></div><div><span>Password</span><code>{credentials.password}</code></div><p>The user can sign in with either Email ID or User ID using this password.</p><button className="button primary" onClick={()=>window.location.assign('/sign-in')}>Open sign in</button></div>}</Panel><Panel title="Organization users"><div className="user-access-list">{data.users.map(user=><button type="button" className="user-access-button" key={user.id} onClick={()=>setEditing(user)}><span className="avatar">{user.name.split(' ').map(p=>p[0]).join('').slice(0,2)}</span><span><b>{user.name}</b><small>{user.email}{user.loginId?` · User ID ${user.loginId}`:' · Primary admin'} · {roleName(user.role)} · {user.role==='ADMIN'?'Full workspace access':user.moduleAccess.map(label).join(', ')}</small></span><Status value={user.status}/><Settings2/></button>)}</div></Panel>{editing&&<EditUserAccess user={editing} close={()=>setEditing(null)} saved={async()=>{setEditing(null);await reload()}}/>}</div>
}
function EditUserAccess({user,close,saved}:{user:Workspace['users'][number];close:()=>void;saved:()=>Promise<void>}){
  const roles:Array<{id:ManagedRole;label:string}>=[{id:'REP',label:'Sales representative'},{id:'MANAGER',label:'Manager'},{id:'FINANCE',label:'Finance'},{id:'ADMIN',label:'Admin'}];
  const initialRole=roles.some(r=>r.id===user.role)?user.role as ManagedRole:'REP';
  const [status,setStatus]=useState(user.status);
  const [role,setRole]=useState<ManagedRole>(initialRole);
  const [modules,setModules]=useState<AccessModuleId[]>(user.role==='ADMIN'?[...accessModules.map(([id])=>id)]:user.moduleAccess as AccessModuleId[]);
  const [busy,setBusy]=useState(false);
  const [error,setError]=useState('');
  const toggle=(id:AccessModuleId)=>setModules(modules.includes(id)?modules.filter(x=>x!==id):[...modules,id]);
  const submit=async(e:FormEvent)=>{
    e.preventDefault();
    try{
      setBusy(true);setError('');
      await request(`/admin/users/${user.id}`,{method:'PATCH',body:JSON.stringify({status,role,moduleAccess:role==='ADMIN'?accessModules.map(([id])=>id):modules})});
      await saved();
    }catch(e){
      setError(e instanceof Error?e.message:'Could not update user');
    }finally{
      setBusy(false);
    }
  };
  return <Modal title={`Edit ${user.name}`} close={close}><form className="form" onSubmit={submit}><label>Status<select value={status} onChange={e=>setStatus(e.target.value)}><option value="ACTIVE">Active</option><option value="DISABLED">Inactive</option><option value="PENDING">Pending</option></select></label><label>Business role<select value={role} onChange={e=>setRole(e.target.value as ManagedRole)}>{roles.map(option=><option key={option.id} value={option.id}>{option.label}</option>)}</select></label><div><b>Accessible modules</b><p className="muted">{role==='ADMIN'?'Admins receive full workspace access.':'Select the modules this user can open.'}</p><div className="module-grid">{accessModules.map(([id,text])=><label className={(role==='ADMIN'||modules.includes(id))?'selected':'disabled'} key={id}><input type="checkbox" checked={role==='ADMIN'||modules.includes(id)} disabled={role==='ADMIN'} onChange={()=>toggle(id)}/><span><Check/>{text}</span></label>)}</div></div>{error&&<div className="error">{error}</div>}<button className="button primary" disabled={busy||role!=='ADMIN'&&!modules.length}>{busy?'Saving...':'Save changes'}</button></form></Modal>
}
function DealTable({quotes,open,fulfillment=false}:{quotes:Quote[];open:(v:View,id?:string)=>void;fulfillment?:boolean}){return <div className="table-wrap"><table><thead><tr><th>Deal</th><th>Customer</th><th>Value</th><th>Stage</th><th>Risk</th><th/></tr></thead><tbody>{quotes.map(q=><tr key={q.id}><td><b>{q.number}</b></td><td>{q.customer}</td><td>{money(q.total)}</td><td><Status value={q.stage}/></td><td>{q.riskScore} pts</td><td><button onClick={()=>open(fulfillment?'fulfillment-detail':'quote',q.id)}>Open <ChevronRight/></button></td></tr>)}</tbody></table>{!quotes.length&&<Empty text="No records match this view."/>}</div>}
function Metric({label:txt,value,note,tone=''}:{label:string;value:string;note:string;tone?:string}){return <div className={`metric ${tone}`}><span>{txt}</span><strong>{value}</strong><small>{note}</small></div>}
function Panel({title:txt,children,action}:{title:string;children:ReactNode;action?:ReactNode}){return <div className="panel"><div className="panel-title"><h3>{txt}</h3>{action}</div>{children}</div>}
function Status({value}:{value:string}){return <span className={`status ${value.toLowerCase()}`}>{label(value)}</span>}
function Empty({text}:{text:string}){return <div className="empty"><Package/><p>{text}</p></div>}
function Modal({title:txt,children,close}:{title:string;children:ReactNode;close:()=>void}){return <div className="modal-wrap" onMouseDown={e=>e.target===e.currentTarget&&close()}><div className="modal"><div className="panel-title"><h3>{txt}</h3><button onClick={close}><X/></button></div>{children}</div></div>}
function title(view:View){const map:Record<View,string>={dashboard:'Sales dashboard',quotations:'Quotation pipeline',quote:'Quotation detail',approvals:'Approval queue',approval:'Approval detail',fulfillment:'Fulfillment & stock','fulfillment-detail':'Fulfillment detail',subscriptions:'Subscriptions',billing:'Billing detail',portal:'Customer portal',invoices:'Invoices',invoice:'Invoice detail',health:'Deal health',reports:'Sales reporting',products:'Products',product:'Product details',customers:'Customers',customer:'Customer detail',policies:'Discount governance',access:'User access control'};return map[view]}
function related(view:View,id:View){return(id==='quotations'&&view==='quote')||(id==='approvals'&&view==='approval')||(id==='fulfillment'&&view==='fulfillment-detail')||(id==='subscriptions'&&view==='billing')||(id==='invoices'&&view==='invoice')||(id==='products'&&view==='product')||(id==='customers'&&view==='customer')}
function CustomerDetailV2(props:{customer?:Customer;open:(v:View,id?:string)=>void;mutate:Function}){const customer=props.customer;const account=customer?.users?.[0];const invitation=customer?.invitations?.[0];const state=account?.status==='ACTIVE'&&account.googleSubject?'CONNECTED':invitation?.status??(customer?.email?'NOT_INVITED':'EMAIL_REQUIRED');return <><CustomerDetail {...props}/>{customer&&<Panel title="Customer portal access" action={<a className="button ghost" href="/customer" target="_blank" rel="noreferrer">Preview portal <ArrowRight/></a>}><div className="portal-access-row"><div><span className={`status ${state.toLowerCase()}`}>{label(state)}</span><h3>{customer.email||'Add an email to invite this customer'}</h3><p>{state==='CONNECTED'?'Google identity verified. New quotations and invoices synchronize automatically.':state==='PENDING'?'Invitation is ready. The customer must use this exact email with Google.':state==='EMAIL_REQUIRED'?'Portal access requires a valid customer email.':'Send a new invitation to activate Google portal access.'}</p>{invitation?.expiresAt&&state==='PENDING'&&<small>Invitation expires {date(invitation.expiresAt)}</small>}</div><button className="button primary" disabled={!customer.email} onClick={()=>props.mutate(`/customers/${customer.id}/portal-invite`,{},'POST',account?.status==='ACTIVE'?'Portal access refreshed':'Customer invitation sent')}><Mail/>{state==='PENDING'?'Resend invitation':'Send invitation'}</button></div></Panel>}</>}
